package com.campusmart.service;
import com.campusmart.entity.Product;import com.campusmart.repository.ProductRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.util.*;
@Service public class AiService{private final ProductRepository products;private final RestClient client;private final String model;public AiService(ProductRepository p,@Value("${app.ai.url}")String url,@Value("${app.ai.model}")String model){products=p;client=RestClient.builder().baseUrl(url).build();this.model=model;}public Map<String,Object>recommend(String requirement){List<Product>candidates=products.search(requirement,null,null,null).stream().limit(12).toList();if(candidates.isEmpty())return Map.of("message","No suitable products were found.","products",List.of());StringBuilder context=new StringBuilder();for(int i=0;i<candidates.size();i++){Product p=candidates.get(i);context.append(i+1).append(". ").append(p.getName()).append(" | ₹").append(p.getPrice()).append(" | ").append(p.getCategory().getName()).append(" | ").append(p.getCondition()).append("\n");}String prompt="You are CampusMart AI, a college marketplace recommendation assistant. User requirement: "+requirement+"\nAvailable products (use only these; never invent):\n"+context+"Recommend the most relevant products briefly. If none fit, say no suitable products were found.";try{Map<String,Object>body=Map.of("model",model,"messages",List.of(Map.of("role","system","content","You recommend only supplied marketplace products."),Map.of("role","user","content",prompt)),"temperature",0.2,"max_tokens",180);Map response=client.post().body(body).retrieve().body(Map.class);Object choices=response==null?null:response.get("choices");if(choices instanceof List<?>list&&!list.isEmpty()&&list.get(0)instanceof Map<?,?>c&&c.get("message")instanceof Map<?,?>msg)return Map.of("message",String.valueOf(msg.get("content")),"products",candidates);throw new IllegalStateException("Unexpected LM Studio response");}catch(Exception ex){throw new IllegalStateException("LM Studio is unavailable. Start the local server and load Gemma 2B.");}}}
